{
  "schemaVersion": "0.2",
  "slug": "edge",
  "name": "Edge",
  "family": "G",
  "status": "experimental",
  "purpose": "Draws a connection line between two canvas points with an optional label.",
  "scenarios": [
    "Link two flow nodes",
    "Show dependency direction",
    "Annotate a connection"
  ],
  "props": {
    "x1": {
      "type": "number",
      "required": true,
      "description": "Start x in world px."
    },
    "y1": {
      "type": "number",
      "required": true,
      "description": "Start y in world px."
    },
    "x2": {
      "type": "number",
      "required": true,
      "description": "End x in world px."
    },
    "y2": {
      "type": "number",
      "required": true,
      "description": "End y in world px."
    },
    "variant": {
      "type": "enum",
      "required": false,
      "description": "Path shape.",
      "values": [
        "bezier",
        "straight"
      ],
      "default": "bezier"
    },
    "label": {
      "type": "string",
      "required": false,
      "description": "Text rendered at the path midpoint."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "variant",
      "values": [
        "bezier",
        "straight"
      ],
      "default": "bezier",
      "description": "Path shape."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Edge rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "canvas",
      "mind-map",
      "graph-view",
      "pipeline-view"
    ],
    "allowedChildren": [],
    "requiredContext": [
      "canvas"
    ]
  },
  "antiPatterns": [
    "Do not use edges for decorative dividers.",
    "Do not draw edges without both endpoints resolved."
  ],
  "a11y": {
    "role": "img",
    "keyboard": [],
    "focus": "Not focusable; relationships are described by node labels.",
    "labeling": "Optional midpoint label is real text.",
    "wcag": [
      "1.1.1"
    ]
  },
  "responsive": {
    "strategy": "Vector path scales with the canvas zoom.",
    "breakpoints": {
      "compact": "Scales with zoom.",
      "medium": "Scales with zoom.",
      "large": "Scales with zoom."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "edge",
    "states": [
      "default"
    ],
    "intents": [
      "connect-nodes"
    ]
  }
}

import './styles.css'

export interface EdgeProps {
  x1: number
  y1: number
  x2: number
  y2: number
  variant?: 'bezier' | 'straight'
  label?: string
  className?: string
}

export function Edge({ x1, y1, x2, y2, variant = 'bezier', label, className }: EdgeProps) {
  const classes = ['cu-edge', className].filter(Boolean).join(' ')
  const left = Math.min(x1, x2)
  const top = Math.min(y1, y2)
  const width = Math.max(1, Math.abs(x2 - x1))
  const height = Math.max(1, Math.abs(y2 - y1))
  const sx = x1 - left
  const sy = y1 - top
  const ex = x2 - left
  const ey = y2 - top
  const path =
    variant === 'straight'
      ? `M ${sx} ${sy} L ${ex} ${ey}`
      : `M ${sx} ${sy} C ${sx + (ex - sx) / 2} ${sy}, ${sx + (ex - sx) / 2} ${ey}, ${ex} ${ey}`

  return (
    <svg
      className={classes}
      data-ai-role="edge" data-ai-intent="connect-nodes"
      data-ai-state="default"
      style={{ insetInlineStart: left, insetBlockStart: top }}
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      role="img"
      aria-label={label}
      aria-hidden={label ? undefined : true}
    >
      <path className="cu-edge__path" d={path} />
      {label ? (
        <text className="cu-edge__label" x={width / 2} y={height / 2} textAnchor="middle">
          {label}
        </text>
      ) : null}
    </svg>
  )
}

.cu-edge {
  position: absolute;
  overflow: visible;
  pointer-events: none;
}

.cu-edge__path {
  fill: none;
  stroke: var(--cu-color-border-default);
  stroke-width: 2;
}

.cu-edge__label {
  fill: var(--cu-color-fg-default);
  font-size: 0.75rem;
}
